import{_ as r,C as n,c as a,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Job positions","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/job-positions/job-positions.md","filePath":"master/human-resources/recruitment/job-positions/job-positions.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/recruitment/job-positions/job-positions.md"};function p(m,e,h,c,g,d){const o=n("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="job-positions" tabindex="-1">Job positions <a class="header-anchor" href="#job-positions" aria-label="Permalink to &quot;Job positions&quot;">​</a></h1><p>A job position is a role you hire for, such as Warehouse Supervisor. In Recruitment, each position appears as a card that shows how many applicants wait in the first stage and how many people you want to hire. The same positions are shared with the Employees app, so one record serves both.</p><blockquote><p><strong>In simple words:</strong> A job position is an open role. Its card is your shortcut to the applicants for that role.</p></blockquote><p>Open <code>Recruitments → Applications → Job Positions</code> to see the cards. Open <code>Recruitments → Configuration → Job Positions</code> to create or edit them.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Create the department first, for example <strong>Operations</strong>. See <a href="./../../employees/departments/departments.html">Departments</a>. The Employees guide also covers positions: <a href="./../../employees/setup/job-positions.html">Job positions in Employees</a>.</p></div><h2 id="overview-the-cards-page" tabindex="-1">Overview: the cards page <a class="header-anchor" href="#overview-the-cards-page" aria-label="Permalink to &quot;Overview: the cards page&quot;">​</a></h2><p>The page shows two cards per row. Each card has the position name in bold. A company line and a manager line appear when the position has them.</p><ul><li>The blue button <strong>N New Applications</strong> counts applicants in the <strong>New</strong> stage. Click it to open the applicants of that job in that stage.</li><li>The three dots menu holds <strong>N To Recruitment</strong> and <strong>N Applications</strong>. <strong>To Recruitment</strong> is the recruitment target and opens the edit page. <strong>Applications</strong> is the total of applicants and opens the applicant list for that job.</li></ul>',8)),s(o,{src:"/images1/recruitment/jp_cards.png",alt:"Job Positions cards page with the Default, My Department and Archived tabs, search box and Sort by menu"}),e[1]||(e[1]=t('<h3 id="preset-tabs-search-and-sort" tabindex="-1">Preset tabs, search and sort <a class="header-anchor" href="#preset-tabs-search-and-sort" aria-label="Permalink to &quot;Preset tabs, search and sort&quot;">​</a></h3><ul><li><strong>Default:</strong> all positions.</li><li><strong>My Department:</strong> positions in your own department.</li><li><strong>Archived:</strong> archived positions.</li></ul><p>Type in the search box to find a card. Use <strong>Sort by</strong> to order cards by <strong>Name</strong> or <strong>Manager</strong>. Choose how many cards show per page at the bottom.</p><h2 id="card-actions" tabindex="-1">Card actions <a class="header-anchor" href="#card-actions" aria-label="Permalink to &quot;Card actions&quot;">​</a></h2><p>Follow these steps for the example position <strong>Warehouse Supervisor</strong>.</p><ol><li>Find the card. Search for it if it is not on the first page.</li><li>Click <strong>New Applications</strong> to see applicants waiting in <strong>New</strong>.</li><li>Open the three dots menu.</li><li>Click <strong>Applications</strong> to see all its applicants, or <strong>To Recruitment</strong> to edit the target.</li></ol>',6)),s(o,{src:"/images1/recruitment/jp_card_menu.png",alt:"Warehouse Supervisor card with the three dots menu open showing To Recruitment and Applications"}),e[2]||(e[2]=t('<h2 id="create-a-job-position" tabindex="-1">Create a job position <a class="header-anchor" href="#create-a-job-position" aria-label="Permalink to &quot;Create a job position&quot;">​</a></h2><p>The cards page has no create button. Use the setup page.</p><ol><li>Open <code>Recruitments → Configuration → Job Positions</code>.</li><li>Click <strong>Job Position</strong> in the page header. A full page opens.</li><li>Fill in the form, using the glossary below.</li><li>Click <strong>Create</strong>.</li></ol>',3)),s(o,{src:"/images1/recruitment/jp_create_form.png",alt:"Create Job Position form filled for Warehouse Supervisor in Operations"}),e[3]||(e[3]=t('<p>This example creates <strong>Warehouse Supervisor</strong> in <strong>Operations</strong>. It comes with the sample data, so open it to compare with your own.</p><h3 id="employment-information" tabindex="-1">Employment Information <a class="header-anchor" href="#employment-information" aria-label="Permalink to &quot;Employment Information&quot;">​</a></h3><ul><li><strong><em>Job Position Title:</em></strong> (required) the official name, for example <strong>Warehouse Supervisor</strong>.</li><li><strong><em>Department:</em></strong> pick <strong>Operations</strong>. You can create a department from the field. This fills <strong>Manager</strong> and <strong>Company</strong> when they are empty.</li><li><strong><em>Manager:</em></strong> the department manager. It follows the department.</li><li><strong><em>Company:</em></strong> starts as your current company. Changing it clears a department or manager from another company.</li><li><strong><em>Recruiter:</em></strong> the user in charge of hiring. You can create a user from the field.</li><li><strong><em>Interviewers:</em></strong> one or more users who interview applicants.</li><li><strong><em>Job Location:</em></strong> an address. You can create one from the field.</li><li><strong><em>Industry:</em></strong> the industry of the role. You can create one from the field.</li><li><strong><em>Job Description</em></strong> and <strong><em>Job Requirements:</em></strong> two text editors. Describe the role and what a person needs to do it.</li></ul><h3 id="side-column" tabindex="-1">Side column <a class="header-anchor" href="#side-column" aria-label="Permalink to &quot;Side column&quot;">​</a></h3><ul><li><strong><em>Date From</em></strong> and <strong><em>Date To:</em></strong> the period the position is open.</li><li><strong><em>Recruitment Target:</em></strong> how many people you want to hire. It starts at <strong>0</strong>. This number is the <strong>To Recruitment</strong> value on the card.</li><li><strong><em>No of employee</em></strong>, <strong><em>Expected employees</em></strong> and <strong><em>No of hired employee:</em></strong> greyed out. Aureus calculates them.</li><li><strong><em>Expected Skills:</em></strong> pick the skills the role needs.</li><li><strong><em>Employment Type:</em></strong> for example <strong>Full-Time</strong>. See <a href="./../../employees/setup/employment-types.html">Employment types</a>.</li><li><strong><em>Status:</em></strong> a toggle. It starts <strong>off</strong> when you create a position. Turn it <strong>on</strong> for an open role.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Turn <strong>Status</strong> on before you save. A new position starts with <strong>Status</strong> off.</p></div>',6)),s(o,{src:"/images1/recruitment/jp_create_side_column.png",alt:"Side column of the job position form with Recruitment Target 2, Expected Skills, Employment Type Full-Time and Status on"}),e[4]||(e[4]=t('<h2 id="view-a-position" tabindex="-1">View a position <a class="header-anchor" href="#view-a-position" aria-label="Permalink to &quot;View a position&quot;">​</a></h2><p>Click <strong>View</strong> on a position in the list. The page shows the same details, plus a <strong>Workforce Planning</strong> card with <strong>Expected Employees</strong>, <strong>Current Employees</strong> and <strong>Recruitment Target</strong>. Click <strong>Edit</strong> to change them.</p>',2)),s(o,{src:"/images1/recruitment/jp_view_page.png",alt:"View page of the Warehouse Supervisor job position with the Workforce Planning card"}),e[5]||(e[5]=t('<h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The list at <code>Recruitments → Configuration → Job Positions</code> has the columns <strong>Job Position</strong>, <strong>Department</strong>, <strong>Company</strong> and <strong>Status</strong>. It can be grouped by company, department or employment type. Edits you make here show in the Employees app too.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../employees/setup/job-positions.html">Job positions in Employees</a></li><li><a href="./../applicants/add-applicant.html">Add an applicant</a></li><li><a href="./../setup/stages.html">Stages</a></li><li><a href="./../dashboard/recruitment-dashboard.html">Recruitment dashboard</a></li></ul>',4))])}const f=r(l,[["render",p]]);export{b as __pageData,f as default};
